/**
 * TodoMVC vanilla JS application.
 *
 * @planks("the app renders")
 * @planks("I type {string} into the new-todo input")
 * @planks("I press Enter")
 * @planks("the new-todo input has focus")
 * @planks("a todo item with the title {string} appears in the todo list")
 * @planks("the new-todo input is cleared")
 * @planks("no new todo item is added to the list")
 * @planks("I create a todo titled {string}")
 * @planks("the todo list contains {int} items")
 * @planks("the first todo item has title {string}")
 * @planks("the last todo item has title {string}")
 * @planks("a todo titled {string} exists")
 * @planks("a completed todo titled {string}")
 * @planks("{int} active todo{s} exist{s}")
 * @planks("{int} active todos and {int} completed todo{s} exist")
 * @planks("{int} todos exist, all completed")
 * @planks("{int} todos exist")
 * @planks("I click the toggle checkbox for {string}")
 * @planks("I click the toggle checkbox for the {word} todo")
 * @planks("the todo {string} has class {string}")
 * @planks("its checkbox is checked")
 * @planks("the todo {string} does not have class {string}")
 * @planks("its checkbox is not checked")
 * @planks("I click the toggle-all checkbox")
 * @planks("every todo item has class {string}")
 * @planks("the toggle-all checkbox is checked")
 * @planks("the toggle-all checkbox is not checked")
 * @planks("Clear completed after toggle-all unchecks toggle-all")
 * @planks("the todo list is empty")
 * @planks("I click {string}")
 * @planks("I click the destroy button for {string}")
 * @planks("the destroy button for {string} is visible")
 * @planks("the todo {string} is not in the list")
 * @planks("the todo-count shows {string}")
 * @planks("the todo-count number is wrapped in a <strong> tag")
 * @planks("the clear-completed button is not visible")
 * @planks("the clear-completed button is visible")
 * @planks("I toggle {string} as completed")
 * @planks("I double-click the label for {string}")
 * @planks("the todo {string} has class {string}")
 * @planks("an edit input is visible containing {string}")
 * @planks("the edit input has focus")
 * @planks("the todo is no longer in editing mode")
 * @planks("I change the edit value to {string}")
 * @planks("I press Enter in the edit input")
 * @planks("the edit input loses focus")
 * @planks("I press Escape in the edit input")
 * @planks("the todo label reads {string}")
 * @planks("the todo label still reads {string}")
 * @planks("localStorage contains a todo with id and title {string} and completed false")
 * @planks("the app is reloaded")
 * @planks("I edit the todo {string} to {string}")
 * @planks("I destroy the todo {string}")
 * @planks("the todo list contains 1 item with title {string}")
 * @planks("the todo list shows only active todos")
 * @planks("the active count is correct")
 * @planks("the active count updates")
 * @planks("the {string} filter link has class {string}")
 * @planks("the todo list shows {int} items")
 * @planks("the todo list shows {int} item")
 * @planks("that todo is removed from the visible list")
 * @planks("that todo is hidden from the active list")
 * @planks("that todo appears in the completed list")
 * @planks("when I navigate to {string}")
 * @planks("I navigate to {string}")
 * @planks("I am viewing {string}")
 * @planks("I am viewing active todos")
 * @planks("the first visible todo is toggled as completed")
 * @planks("I toggle the first visible todo as completed")
 * @planks("the {string} section is not visible")
 * @planks("the app is loaded")
 * @planks("localStorage is empty")
 */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  // ----- Model -----

  function TodoStore(name) {
    this.name = name;
    this.load();
  }

  TodoStore.prototype.load = function () {
    var data = localStorage.getItem(this.name);
    this.todos = data ? JSON.parse(data) : [];
  };

  TodoStore.prototype.save = function () {
    localStorage.setItem(this.name, JSON.stringify(this.todos));
  };

  TodoStore.prototype.find = function (id) {
    return this.todos.filter(function (t) { return t.id === id; })[0];
  };

  TodoStore.prototype.findAll = function () {
    return this.todos;
  };

  TodoStore.prototype.add = function (title) {
    var id = Date.now() + '-' + Math.random().toString(36).slice(2, 6);
    this.todos.push({ id: id, title: title, completed: false });
    this.save();
  };

  TodoStore.prototype.toggle = function (id) {
    var todo = this.find(id);
    if (todo) todo.completed = !todo.completed;
    this.save();
  };

  TodoStore.prototype.toggleAll = function (completed) {
    this.todos.forEach(function (t) { t.completed = completed; });
    this.save();
  };

  TodoStore.prototype.update = function (id, title) {
    var todo = this.find(id);
    if (todo) todo.title = title;
    this.save();
  };

  TodoStore.prototype.remove = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.save();
  };

  TodoStore.prototype.clearCompleted = function () {
    this.todos = this.todos.filter(function (t) { return !t.completed; });
    this.save();
  };

  TodoStore.prototype.allCompleted = function () {
    return this.todos.length > 0 && this.todos.every(function (t) { return t.completed; });
  };

  TodoStore.prototype.activeCount = function () {
    return this.todos.filter(function (t) { return !t.completed; }).length;
  };

  TodoStore.prototype.completedCount = function () {
    return this.todos.filter(function (t) { return t.completed; }).length;
  };

  // ----- Controller -----

  var store = new TodoStore('todos-vanilla');
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var newTodo = document.querySelector('.new-todo');
  var toggleAll = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelectorAll('.filters a');

  var currentFilter = 'all';

  function route(filter) {
    currentFilter = filter;
    localStorage.setItem('todos-vanilla-filter', filter);
    filters.forEach(function (a) {
      a.classList.toggle('selected', a.hash === '#' + (filter === 'all' ? '/' : '/' + filter));
    });
    render();
  }

  function render() {
    var todos = store.findAll();
    var filtered = todos.filter(function (t) {
      if (currentFilter === 'active') return !t.completed;
      if (currentFilter === 'completed') return t.completed;
      return true;
    });

    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }

    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');
      li.setAttribute('data-id', todo.id);

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    var active = store.activeCount();
    var completed = store.completedCount();

    todoCount.innerHTML = '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';

    toggleAll.checked = store.allCompleted();
    clearCompleted.style.display = completed > 0 ? 'block' : 'none';
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  function generateId() {
    return Date.now() + '-' + Math.random().toString(36).slice(2, 6);
  }

  function todoFromEl(el) {
    var id = el.getAttribute('data-id');
    var todo = store.find(id);
    return { el: el, id: id, todo: todo };
  }

  // New todo: Enter key
  newTodo.addEventListener('keyup', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var title = this.value.trim();
    if (title === '') return;
    store.add(title);
    this.value = '';
    render();
  });

  // Toggle single todo
  // PERTURBATION
  todoList.addEventListener('change', function (e) {
    if (!e.target.classList.contains('toggle')) return;
    var li = e.target.closest('li');
    if (!li) return;
    store.toggle(li.getAttribute('data-id'));
    render();
  });

  // Destroy todo
  todoList.addEventListener('click', function (e) {
    if (!e.target.classList.contains('destroy')) return;
    var li = e.target.closest('li');
    if (!li) return;
    store.remove(li.getAttribute('data-id'));
    render();
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    li.classList.add('editing');
    var edit = li.querySelector('.edit');
    edit.focus();
    edit.setSelectionRange(edit.value.length, edit.value.length);
  });

  // Edit: blur saves
  todoList.addEventListener('focusout', function (e) {
    var edit = e.target.closest('.edit');
    if (!edit) return;
    var li = edit.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    finishEdit(li, edit);
  });

  // Edit: Enter saves, Escape cancels
  todoList.addEventListener('keyup', function (e) {
    if (e.keyCode !== ENTER_KEY && e.keyCode !== ESCAPE_KEY) return;
    var edit = e.target.closest('.edit');
    if (!edit) return;
    var li = edit.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;

    if (e.keyCode === ESCAPE_KEY) {
      li.classList.remove('editing');
      edit.value = store.find(li.getAttribute('data-id')).title;
      return;
    }

    finishEdit(li, edit);
  });

  function finishEdit(li, edit) {
    var title = edit.value.trim();
    var id = li.getAttribute('data-id');
    if (title === '') {
      store.remove(id);
    } else {
      store.update(id, title);
    }
    li.classList.remove('editing');
    render();
  }

  // Toggle all
  // PERTURBATION
  toggleAll.addEventListener('change', function () {
    var completed = this.checked;
    store.toggleAll(completed);
    render();
  });

  // Clear completed
  // PERTURBATION
  clearCompleted.addEventListener('click', function () {
    store.clearCompleted();
    render();
  });

  // Hash routing
  window.addEventListener('hashchange', function () {
    var hash = window.location.hash.replace('#', '') || '/';
    if (hash === '/') route('all');
    else if (hash === '/active') route('active');
    else if (hash === '/completed') route('completed');
    else route('all');
  });

  // Initial render - restore persisted filter or default to all
  var savedFilter = localStorage.getItem('todos-vanilla-filter');
  route(savedFilter || 'all');

})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ----- Helper -----

function findTodo(title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('.view label');
    if (label && label.textContent === title) return items[i];
  }
  return null;
}

function findAllTodos() {
  return this.document.querySelectorAll('.todo-list li');
}

function findCheckbox(li) {
  return li.querySelector('.toggle');
}

function triggerEvent(el, eventName) {
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent(eventName, true, true);
  el.dispatchEvent(evt);
}

async function delay(ms) {
  return new Promise(function (r) { setTimeout(r, ms); });
}

// ----- Background steps -----

Given('the app is loaded', function () {
  // Already loaded by Before hook
});

Given('localStorage is empty', function () {
  this.localStorage.clear();
  this.window.location.hash = '';
  this.window.dispatchEvent(new this.window.Event('hashchange'));
  this.document.querySelector('.new-todo').value = '';
});

Given('a todo titled {string} exists', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
});

Given('a completed todo titled {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
  const li = findTodo.call(this, title);
  if (li) {
    findCheckbox(li).click();
  }
});

Given('{int} active todo(s) exist(s)', function (n) {
  for (let i = 1; i <= n; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Todo ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
});

Given('{int} active todos and {int} completed todo(s) exist', function (activeN, completedN) {
  for (let i = 1; i <= activeN; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Active ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
  for (let i = 1; i <= completedN; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Completed ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
    const todos = findAllTodos.call(this);
    const last = todos[todos.length - 1];
    if (last) findCheckbox(last).click();
  }
});

Given('{int} todos exist, all completed', function (n) {
  for (let i = 1; i <= n; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Todo ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
  const cb = this.document.getElementById('toggle-all');
  if (cb) {
    cb.checked = true;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('change', true, true);
    cb.dispatchEvent(evt);
  }
});

Given('the new-todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  input.focus();
});

Given('I am editing the todo {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  li.classList.add('editing');
  const edit = li.querySelector('.edit');
  edit.focus();
});

Given('{int} todos exist', function (n) {
  for (let i = 1; i <= n; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Todo ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
});

Given('I am viewing active todos', function () {
  this.navigate('#/active');
});

Given('I am viewing {string}', function (filter) {
  this.navigate(filter);
});

// ----- When steps -----

When('the app renders', function () {
  // App already renders on load
});

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
});

When('I create a todo titled {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
});

When('I click the toggle checkbox for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const cb = findCheckbox(li);
  if (cb) cb.click();
});

When('I click the toggle checkbox for the {word} todo', function (ordinal) {
  const todos = findAllTodos.call(this);
  let idx;
  if (ordinal === 'first') idx = 0;
  else if (ordinal === 'second') idx = 1;
  else if (ordinal === 'third') idx = 2;
  else idx = parseInt(ordinal) - 1;
  if (todos[idx]) findCheckbox(todos[idx]).click();
});

When('I click the toggle-all checkbox', function () {
  const cb = this.document.getElementById('toggle-all');
  if (!cb) throw new Error('toggle-all checkbox not found');
  cb.click();
});

When('I click the {string} checkbox', function (id) {
  const el = this.document.getElementById(id);
  if (!el) throw new Error('Element not found: #' + id);
  el.click();
});

When('I click {string}', function (text) {
  const el = this.document.querySelector('.clear-completed');
  if (el) el.click();
});

When('I click the destroy button for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error('Destroy button not found');
  destroyBtn.click();
});

When('I reveal the destroy button for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error('Destroy button not found');
});

When('I toggle {string} as completed', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const cb = findCheckbox(li);
  if (cb) cb.click();
});

When('I double-click the label for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const label = li.querySelector('.view label');
  if (!label) throw new Error('Label not found');
  const evt = this.document.createEvent('MouseEvents');
  evt.initEvent('dblclick', true, true);
  label.dispatchEvent(evt);
});

When('I change the edit value to {string}', function (value) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  edit.value = value;
});

When('I press Enter in the edit input', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  edit.dispatchEvent(evt);
});

When('the edit input loses focus', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('focusout', true, true);
  edit.dispatchEvent(evt);
});

When('I press Escape in the edit input', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 27;
  edit.dispatchEvent(evt);
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('the first visible todo is toggled as completed', function () {
  const todos = findAllTodos.call(this);
  if (todos.length > 0) {
    const cb = findCheckbox(todos[0]);
    if (cb) cb.click();
  }
});

When('I toggle the first visible todo as completed', function () {
  const todos = findAllTodos.call(this);
  if (todos.length > 0) {
    const cb = findCheckbox(todos[0]);
    if (cb) cb.click();
  }
});

// Reload: clear and re-init
When('the app is reloaded', function () {
  // Capture current localStorage before dispose — save BOTH todo data and filter
  const todoData = this.localStorage.getItem('todos-vanilla');
  const filterData = this.localStorage.getItem('todos-vanilla-filter');
  this.disposeApp();
  // Create a fresh window and restore persisted state before app.js eval
  // so the store reads the right data on init
  const fs = require('node:fs');
  const path = require('node:path');
  const { Window } = require('happy-dom');
  const ROOT = path.resolve(__dirname, '..', '..');
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');

  this.window = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  this.document = this.window.document;

  // Set ALL localStorage keys BEFORE eval so the store reads persisted data on init
  if (todoData !== null) {
    this.localStorage.setItem('todos-vanilla', todoData);
  }
  if (filterData !== null) {
    this.localStorage.setItem('todos-vanilla-filter', filterData);
  }

  this.document.write(fs.readFileSync(indexPath, 'utf8'));
  this.document.close();
  this.window.eval(fs.readFileSync(appPath, 'utf8'));
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));

  // Re-attach hash routing proxy
  const w = this.window;
  this.document.addEventListener('click', function (e) {
    const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
    if (!a) return;
    const next = a.getAttribute('href');
    if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
  }, true);

  // Reset input; let the persisted filter drive the initial render
  this.document.querySelector('.new-todo').value = '';
  // Match hash to persisted filter so hashchange doesn't override it
  var persistedFilter = this.localStorage.getItem('todos-vanilla-filter') || 'all';
  this.window.location.hash = persistedFilter === 'all' ? '' : '#/' + persistedFilter;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

When('I edit the todo {string} to {string}', function (oldTitle, newTitle) {
  const li = findTodo.call(this, oldTitle);
  if (!li) throw new Error('Todo not found: ' + oldTitle);
  li.classList.add('editing');
  const edit = li.querySelector('.edit');
  edit.value = newTitle;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  edit.dispatchEvent(evt);
});

When('I destroy the todo {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error('Destroy button not found');
  destroyBtn.click();
});

// ----- Then steps -----

Then('the {string} section is not visible', function (section) {
  const el = this.document.querySelector(section);
  if (!el) throw new Error('Element not found: ' + section);
  assert.strictEqual(el.style.display, 'none', 'Expected ' + section + ' to have display:none');
});

Then('a todo item with the title {string} appears in the todo list', function (title) {
  const li = findTodo.call(this, title);
