  const source = fs.readFileSync(fullPath, 'utf8');
  assert.ok(source.trim().length > 0, 'Expected non-empty source at ' + fullPath);
  this.toggleSource = source;
  this.toggleSourcePath = fullPath;
});

When('the verifier checks the toggle-todo seam against the scantling at {string}', function (scantlingPath) {
  const fs = require('node:fs');
  const path = require('node:path');
  const assert = require('node:assert');
  const ROOT = path.resolve(__dirname, '..', '..');
  const fullPath = path.join(ROOT, scantlingPath);
  assert.ok(fs.existsSync(fullPath), 'Expected scantling at ' + fullPath);
  const scantling = JSON.parse(fs.readFileSync(fullPath, 'utf8'));
  // Run the dynamic identity check per the scantling's counterexample definition:
  // Query .todo-list li before toggle, store refs keyed by data-id.
  // After toggle, verify that elements with the same data-id are the same
  // element reference at the same index position.
  var counterexamples = [];
  var doc = this.document;
  var win = this.window;
  // Create 3 todos to have a list to check
  function createTodo(title) {
    var input = doc.querySelector('.new-todo');
    input.value = title;
    var evt = doc.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
  createTodo('First todo');
  createTodo('Second todo');
  createTodo('Third todo');
  // Capture pre-state references
  var preItems = doc.querySelectorAll('.todo-list li');
  var preMap = {};
  for (var i = 0; i < preItems.length; i++) {
    var id = preItems[i].getAttribute('data-id');
    if (!id) continue;
    preMap[id] = { ref: preItems[i], index: i };
  }
  // Perform a single toggle on the first todo checkbox
  var firstCheckbox = preItems[0] && preItems[0].querySelector('.toggle');
  if (firstCheckbox) {
    firstCheckbox.click();
  }
  // Capture post-state references
  var postItems = doc.querySelectorAll('.todo-list li');
  // Check identity preservation
  for (var id in preMap) {
    var preEntry = preMap[id];
    var postRef = null;
    var postIndex = -1;
    for (var j = 0; j < postItems.length; j++) {
      if (postItems[j].getAttribute('data-id') === id) {
        postRef = postItems[j];
        postIndex = j;
        break;
      }
    }
    if (postRef === null) {
      counterexamples.push('Element with data-id "' + id + '" was not found after toggle');
    } else if (postRef !== preEntry.ref) {
      counterexamples.push('Element with data-id "' + id + '" changed identity: was ' +
        preEntry.ref.outerHTML + ', now ' + postRef.outerHTML);
    } else if (postIndex !== preEntry.index) {
      counterexamples.push('Element with data-id "' + id + '" moved from index ' +
        preEntry.index + ' to ' + postIndex);
    }
  }
  this.identityCounterexamples = counterexamples;
});

Then('no counterexample is found', function () {
  var cex = this.identityCounterexamples || [];
  assert.strictEqual(cex.length, 0,
    'Expected no counterexamples, but found ' + cex.length + ': ' + JSON.stringify(cex));
});

